function sumFourDivisors(nums) {
  const limit = Math.max(...nums);
  const smallest = new Array(limit + 1).fill(0);
  for (let i = 2; i <= limit; i++) {
    if (smallest[i] === 0) {
      for (let j = i; j <= limit; j += i) {
        if (smallest[j] === 0) {
          smallest[j] = i;
        }
      }
    }
  }
  let total = 0;
  for (const num of nums) {
    if (num < 2) {
      continue;
    }
    const p = smallest[num];
    const q = num / p;
    const isPrimeProduct = q !== p && smallest[q] === q;
    const isPrimeCube = q === p * p;
    if (isPrimeProduct || isPrimeCube) {
      total += 1 + p + q + num;
    }
  }
  return total;
}

