function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const small = size === 'small';
  const top = small ? (rand() < 0.8 ? 200 : 100000) : 100000;
  // Primes up to top / 2, used to build values with exactly four divisors on purpose.
  const half = Math.max(2, Math.floor(top / 2));
  const composite = new Uint8Array(half + 1);
  const primes = [];
  for (let i = 2; i <= half; i++) {
    if (composite[i]) continue;
    primes.push(i);
    for (let j = i * i; j <= half; j += i) composite[j] = 1;
  }
  const special = () => {
    if (rand() < 0.2) {
      const cubes = primes.filter(p => p * p * p <= top);
      const p = cubes[pick(cubes.length)];
      return p * p * p;
    }
    for (;;) {
      const p = primes[pick(Math.min(primes.length, 30))];
      const q = primes[pick(primes.length)];
      if (p !== q && p * q <= top) return p * q;
    }
  };
  const n = small ? 1 + pick(8) : 1500 + pick(501);
  const nums = [];
  for (let i = 0; i < n; i++) {
    const roll = rand();
    if (roll < 0.4) nums.push(special());
    else if (roll < 0.5 && nums.length > 0) nums.push(nums[pick(nums.length)]);
    else if (roll < 0.55) nums.push(1);
    else nums.push(1 + pick(top));
  }
  return [nums];
}
